PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE "users" ("user_id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "role" varchar not null default 'admin');
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE "spareparts" ("id_sparepart" integer primary key autoincrement not null, "nama_sparepart" varchar not null, "kode_part" varchar not null, "kategori" varchar not null, "harga" integer not null, "stok" integer not null default ('0'), "stok_minimum" integer not null default ('5'), "created_at" datetime, "updated_at" datetime, "keterangan" varchar, "status" varchar not null default ('aktif'));
CREATE TABLE "barang_masuk" ("id" integer primary key autoincrement not null, "sparepart_id" integer not null, "jumlah" integer not null, "tanggal" date not null, "created_at" datetime, "updated_at" datetime, "keterangan" varchar, "status" varchar not null default ('valid'), foreign key("sparepart_id") references spareparts("id_sparepart") on delete no action on update no action);
CREATE TABLE "barang_keluar" ("id" integer primary key autoincrement not null, "sparepart_id" integer not null, "jumlah" integer not null, "tanggal" date not null, "created_at" datetime, "updated_at" datetime, "status" varchar not null default ('valid'), "keterangan" varchar, foreign key("sparepart_id") references spareparts("id_sparepart") on delete no action on update no action);
CREATE TABLE "sparepart_logs" ("id" integer primary key autoincrement not null, "nama_sparepart" varchar not null, "kode_part" varchar not null, "kategori" varchar not null, "harga" numeric not null, "stok" integer not null, "tipe" varchar not null, "created_at" datetime, "updated_at" datetime, "old_nama_sparepart" varchar, "old_kode_part" varchar, "old_kategori" varchar, "old_harga" integer);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "spareparts_kode_part_unique" on "spareparts" ("kode_part");
COMMIT;
